project_description:
Twig filter rendering tables of contents via TOC API . 

 Usage 


{% set body = content.body|render|toc %}

{{ body.toc }}

{{ body.content }} 

 {# OR #}

 {% set body = content.body|render|toc('full') %}

{{ body.toc }}

{{ body.content }}

 {# OR #}

 {% set toc_options = {

 'header_min': 2,

 'header_max': 4,

} %}

{% set body = content.body|render|toc(toc_options) %}

{{ body.toc }}

{{ body.content }}
